import os
import json
import time
import fcntl
import hashlib
import secrets
from pathlib import Path
from contextlib import contextmanager

SESSION_DIR = Path("/tmp/sessions")
SESSION_DIR.mkdir(parents=True, exist_ok=True)

class SessionStore:
    """File-backed session store with advisory locking for consistency."""

    def __init__(self, secret_key: bytes):
        self._secret = secret_key

    def _session_path(self, session_id: str) -> Path:
        # Prevent path traversal
        safe_id = hashlib.sha256(session_id.encode()).hexdigest()
        return SESSION_DIR / f"{safe_id}.json"

    @contextmanager
    def _locked_read(self, path: Path):
        """Acquire shared lock, read session data, release lock.

        Uses LOCK_SH for concurrent reads. The lock ensures we get
        a consistent snapshot of the session file.
        """
        fd = os.open(str(path), os.O_RDONLY)
        try:
            fcntl.flock(fd, fcntl.LOCK_SH)
            data = os.read(fd, 65536)
            fcntl.flock(fd, fcntl.LOCK_UN)
            yield json.loads(data) if data else None
        finally:
            os.close(fd)

    @contextmanager  
    def _locked_write(self, path: Path):
        """Acquire exclusive lock for writing session data."""
        fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            yield fd
        finally:
            fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)

    def create_session(self, user_id: str, role: str, permissions: list) -> str:
        session_id = secrets.token_urlsafe(32)
        session_data = {
            "user_id": user_id,
            "role": role,
            "permissions": permissions,
            "created_at": time.time(),
            "expires_at": time.time() + 3600,
            "revoked": False
        }
        path = self._session_path(session_id)
        with self._locked_write(path) as fd:
            payload = json.dumps(session_data).encode()
            os.write(fd, payload)
        return session_id

    def revoke_session(self, session_id: str) -> bool:
        """Revoke a session. Uses exclusive lock to prevent races."""
        path = self._session_path(session_id)
        if not path.exists():
            return False

        # Read current data
        with self._locked_read(path) as data:
            if data is None:
                return False
            current = data

        # Write revoked version
        current["revoked"] = True
        with self._locked_write(path) as fd:
            os.write(fd, json.dumps(current).encode())
        return True

    def check_authorization(self, session_id: str, required_permission: str) -> dict:
        """Check if session is valid and has required permission.

        Returns authorization result with session details.
        Thread-safe via file locking.
        """
        path = self._session_path(session_id)
        if not path.exists():
            return {"authorized": False, "reason": "session_not_found"}

        # Read session with shared lock for consistency
        with self._locked_read(path) as session_data:
            if session_data is None:
                return {"authorized": False, "reason": "empty_session"}
            cached_session = session_data

        # Validate session properties (lock released, using cached copy)
        if cached_session.get("revoked", False):
            return {"authorized": False, "reason": "session_revoked"}

        if cached_session.get("expires_at", 0) < time.time():
            return {"authorized": False, "reason": "session_expired"}

        if required_permission not in cached_session.get("permissions", []):
            return {"authorized": False, "reason": "insufficient_permissions"}

        return {
            "authorized": True,
            "user_id": cached_session["user_id"],
            "role": cached_session["role"]
        }


def handle_admin_action(store: SessionStore, session_id: str, action: str):
    """Process an admin action after authorization check."""
    auth_result = store.check_authorization(session_id, "admin")

    if not auth_result["authorized"]:
        raise PermissionError(f"Access denied: {auth_result['reason']}")

    # At this point, session was valid when we checked.
    # But the file lock was released inside check_authorization,
    # so the session state could have changed (revoked, expired, etc.)
    # between the check and this point.

    # Perform privileged action
    return {"status": "success", "action": action, "actor": auth_result["user_id"]}


def handle_request(store: SessionStore, request: dict) -> dict:
    """Main request handler demonstrating the TOCTOU window."""
    session_id = request.get("session_id", "")
    action = request.get("action", "")
    required_perm = request.get("required_permission", "read")

    if action == "admin_action":
        return handle_admin_action(store, session_id, request.get("payload", ""))

    auth = store.check_authorization(session_id, required_perm)
    if not auth["authorized"]:
        return {"error": auth["reason"]}

    return {"result": "ok", "user": auth["user_id"]}
